: "7abe2632cd820c4889b03f22d3a8a9fb7415628fa7d9054d6353be198c4003e0", "src/app/explore/page.tsx": "b9c1d50345ad45c885485686c33fced2f0ee2cad2dfd6d42126cd1ed9bb7d712", "capstone/HEADER_MENU_UPDATE.md": "9f888bb693108a7f39b5d6739724ea29131f9d702e58f0c38f62e4ef7de73741"};
function stop(message){console.error('Stopped: '+message);process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/components/layout/AppHeader.tsx'))stop('Run from your existing project root.');
const root=process.cwd(),backupRoot='.stem-tutor-backups';
function safe(file){let current=root;for(const part of file.split('/')){current=path.join(current,part);try{if(fs.lstatSync(current).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
let previous=null;
if(fs.existsSync(backupRoot)){
 safe(backupRoot);
 const choices=fs.readdirSync(backupRoot).filter(name=>name.startsWith('header-menus-')).map(name=>path.join(backupRoot,name)).filter(dir=>fs.existsSync(path.join(dir,'src/components/layout/AppHeader.tsx'))).sort((a,b)=>fs.statSync(b).mtimeMs-fs.statSync(a).mtimeMs);
 previous=choices[0]||null;
}
const changes=new Map(),deletions=[];
const headerFile='src/components/layout/AppHeader.tsx',exploreFile='src/app/explore/page.tsx';
let header=previous?fs.readFileSync(path.join(previous,headerFile),'utf8'):fallback[headerFile];
// Keep the original dropdown and CTA styling. Merge just the redundant entry.
header=header.replace(/\{\s*label:\s*['"]Explore topics['"],\s*href:\s*['"]\/explore['"]\s*\},?/g,'');
header=header.replace(/<Link href="\/simulations"/g,'<Link href="/explore"').replace(/Try\s+AI/g,'Try now');
if(!header.includes('<SimulationsMenu')||!header.includes('<SimulationsMobileMenu')||!header.includes('Try now'))stop('The previous header could not be identified safely.');
changes.set(headerFile,header);
changes.set(exploreFile,previous&&fs.existsSync(path.join(previous,exploreFile))?fs.readFileSync(path.join(previous,exploreFile),'utf8'):fallback[exploreFile]);
// Remove only unchanged files introduced by the unwanted menu patch.
for(const file of ['src/app/simulations/all/page.tsx','capstone/HEADER_MENU_UPDATE.md']){
 safe(file);if(!fs.existsSync(file))continue;
 const hash=crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
 if(hash===hashes[file])deletions.push(file);else console.log('Preserved later edits in '+file+' (it will no longer be linked from the header).');
}
for(const [file,text] of [...changes]){safe(file);if(fs.existsSync(file)&&fs.readFileSync(file,'utf8')===text)changes.delete(file);}
if(!changes.size&&!deletions.length){console.log('Original dropdown and Try now label are already restored.');process.exit(0);}
fs.mkdirSync(backupRoot,{recursive:true});const safety=fs.mkdtempSync(path.join(backupRoot,'restore-original-menu-')),originals=new Map();
for(const file of [...changes.keys(),...deletions]){
 const original=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,original);
 if(original!==null){const copy=path.join(safety,file);fs.mkdirSync(path.dirname(copy),{recursive:true});fs.writeFileSync(copy,original);}
}
fs.writeFileSync(path.join(safety,'manifest.json'),JSON.stringify([...originals].map(([file,original])=>({file,existed:original!==null})),null,2));
try{for(const [file,text] of changes){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,text,'utf8');}for(const file of deletions)fs.unlinkSync(file);}catch(error){for(const [file,original] of originals){if(original===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,original);}stop('Write failed; current files were restored: '+error.message);}
console.log('Restored the original Simulations subject dropdown and Try now label.');
console.log('Only intended merge retained: Try now opens /explore; no separate Explore topics menu.');
console.log('Original /simulations page and mobile/explainer fixes retained.');
console.log('Backup: '+safety);console.log('Restart npm run dev and refresh your browser.');
AF_RESTORE_ORIGINAL_MENU_NODE
